-- Speaking prompt library: 25 prompts, A1-C2.
-- ============================================================================
-- Rewrites the three original prompts (same slugs, so past attempts stay
-- linked) and adds 22 more: A1 4, A2 5, B1 5, B2 5, C1 4, C2 2.
-- Task types (metadata.task_type): describe, explain, opinion, story,
-- roleplay (request / complaint / negotiation) and presentation. prompt_type
-- keeps the existing check constraint values.
--
-- metadata.model_opening  one sentence learners can hear before they speak.
-- metadata.model_answer   an example answer, shown only after submitting
--                         (the edge function strips it from GET responses).
-- metadata.cue_keywords   per cue point, words the basic (non-AI) check looks
--                         for; also stripped from GET responses.
--
-- Every prompt is registered as a 'speaking.prompt' item in
-- learning_content_registry_items (estimated_minutes = ceil(target/60) + 4).
-- Idempotent: upserts on the existing unique keys. No schema changes.
-- ============================================================================

insert into public.speaking_prompts (
  product_id, language_id, slug, title, prompt_text, prompt_type, level,
  target_duration_seconds, target_grammar, target_vocabulary, fluency_objective,
  pronunciation_objective, cue_points, status, sort_order, metadata
)
select
  p.id, l.id, v.slug, v.title, v.prompt_text, v.prompt_type, v.level,
  v.target_duration_seconds, v.target_grammar, v.target_vocabulary, v.fluency_objective,
  v.pronunciation_objective, v.cue_points, 'published', v.sort_order, v.metadata
from (values
  ('talk-about-your-family',
   'Talk About Your Family',
   'A new friend wants to know about your family. Say who is in your family, give some names or ages, say what they do, and say what you like to do together.',
   'guided_response',
   'A1',
   30,
   'have / has and the present simple',
   array['mother', 'father', 'brother', 'sister', 'older', 'younger', 'together']::text[],
   'Say short, complete sentences one after another without long stops.',
   'Say the -s ending clearly in ''he works'' and ''she likes''.',
   '["who is in your family", "names or ages", "what they do", "what you do together"]'::jsonb,
   10,
   '{"task_type": "describe", "model_opening": "There are five people in my family.", "model_answer": "There are five people in my family. My father, Akmal, is a driver, and my mother is a teacher. I have an older brother and a younger sister. My sister is eight. On Sundays we eat together and watch films.", "cue_keywords": [["mother", "father", "brother", "sister", "parents", "grandmother", "grandfather", "family", "son", "daughter", "wife", "husband"], ["name", "years old", "old", "age", "called", "is"], ["works", "work", "teacher", "doctor", "student", "studies", "school", "job", "driver", "engineer", "nurse", "university"], ["together", "we play", "we eat", "we watch", "we go", "we visit", "we cook", "weekend", "sunday", "saturday"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('your-morning-routine',
   'Your Morning Routine',
   'Tell a classmate about your usual morning on a school or work day. Say when you get up, what you eat or drink, how you travel, and when you arrive.',
   'guided_response',
   'A1',
   30,
   'present simple with time words (at seven o''clock, usually, then)',
   array['usually', 'get up', 'breakfast', 'then', 'by bus', 'on foot', 'arrive']::text[],
   'Use ''then'' and ''after that'' to move from one action to the next.',
   'Say times clearly: seven, seven thirty, eight o''clock.',
   '["when you get up", "what you eat or drink", "how you travel", "when you arrive"]'::jsonb,
   20,
   '{"task_type": "describe", "model_opening": "On school days I usually get up at seven o''clock.", "model_answer": "On school days I usually get up at seven o''clock. I wash my face and get dressed. Then I have breakfast. I eat bread and eggs and drink green tea. I go to school by bus. I arrive at a quarter past eight.", "cue_keywords": [["get up", "wake up", "o''clock", "six", "seven", "eight", "early"], ["eat", "drink", "breakfast", "tea", "bread", "eggs", "coffee", "milk", "porridge"], ["bus", "walk", "metro", "car", "taxi", "bike", "on foot", "by", "drive"], ["arrive", "get to", "start", "at school", "at work", "class", "lessons"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('your-favourite-food',
   'Your Favourite Food',
   'A friend is cooking dinner for you. Tell them what food you like, why you like it, what food you don''t like, and what you like to drink.',
   'guided_response',
   'A1',
   30,
   'like / don''t like + noun, and because',
   array['favourite', 'delicious', 'sweet', 'spicy', 'vegetables', 'because', 'don''t like']::text[],
   'Give a reason with ''because'' after each thing you like.',
   'Make ''I like'' and ''I don''t like'' sound clearly different.',
   '["a food you love", "why you like it", "a food you don''t like", "a drink you like"]'::jsonb,
   30,
   '{"task_type": "opinion", "model_opening": "My favourite food is plov.", "model_answer": "My favourite food is plov. I love it because it is delicious, and my mother makes it every Friday. I also like fresh fruit, especially grapes. I don''t like spicy food. It is too hot for me. My favourite drink is green tea.", "cue_keywords": [["love", "like", "favourite", "plov", "soup", "samsa", "pizza", "fruit", "rice", "meat", "bread", "salad", "chicken"], ["because", "tasty", "delicious", "sweet", "healthy", "good"], ["don''t like", "do not like", "doesn''t", "hate", "not like", "too spicy", "too sweet"], ["drink", "tea", "juice", "water", "milk", "coffee", "ayran", "lemonade"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('buy-fruit-at-the-bazaar',
   'Buy Fruit at the Bazaar',
   'You are at a fruit stall at the bazaar. Speak to the seller: say hello, ask for the fruit you want and how much, ask the price, and say thank you.',
   'roleplay',
   'A1',
   30,
   'Can I have …? / I''d like … / How much is …?',
   array['Can I have', 'I''d like', 'a kilo of', 'How much', 'please', 'thank you']::text[],
   'Speak in short, polite sentences one after another.',
   'Let your voice go up at the end of yes/no questions like ''Are they sweet?''',
   '["greet the seller", "ask for some fruit", "ask the price", "say thank you"]'::jsonb,
   40,
   '{"task_type": "roleplay", "model_opening": "Good morning! Can I have a kilo of apples, please?", "model_answer": "Good morning! Can I have a kilo of apples, please? And I''d like some grapes too. Are they sweet? How much is that, please? Fifteen thousand som? OK, here you are. Thank you very much. Goodbye!", "cue_keywords": [["hello", "hi", "good morning", "good afternoon", "good evening", "salaam", "assalomu"], ["can i have", "i''d like", "i would like", "i want", "apples", "grapes", "melon", "kilo", "pears", "peaches", "bananas", "oranges"], ["how much", "price", "cost", "som"], ["thank", "thanks", "goodbye", "bye"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('new-teammate-introduction',
   'Introduce Yourself to a New Teammate',
   'You have just joined a new team at work or a new study group. Introduce yourself: say your name and where you are from, what you do or study, and what you like doing in your free time. Then ask your new teammate one question.',
   'guided_response',
   'A2',
   45,
   'present simple and question forms',
   array['I''m from', 'I work as', 'I study', 'in my free time', 'I enjoy', 'nice to meet you', 'What about you']::text[],
   'Join your sentences with ''and'', ''but'' and ''so'' instead of stopping after each one.',
   'Let your voice go up at the end of your question so it sounds friendly.',
   '["your name and where you are from", "what you do or study", "your free time", "ask one question"]'::jsonb,
   110,
   '{"task_type": "describe", "model_opening": "Hi, nice to meet you! My name is Dilnoza, and I''m from Namangan.", "model_answer": "Hi, nice to meet you! My name is Dilnoza, and I''m from Namangan, but now I live in Tashkent. I work as a junior designer, so I usually make pictures for websites. In my free time I enjoy cooking, and I play volleyball with my friends on Saturdays. I''m happy to join this team. What about you? How long have you worked here?", "cue_keywords": [["name", "i''m", "from", "live"], ["work", "study", "student", "job", "university", "college", "designer", "engineer", "teacher", "manager", "accountant"], ["free time", "hobby", "enjoy", "weekend", "play", "read", "like"], ["what about you", "do you", "are you", "have you", "how long", "where do", "what do", "how about"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('tell-a-friend-about-your-weekend',
   'Tell a Friend About Your Weekend',
   'A friend asks, ''How was your weekend?'' Tell them where you went, who you were with, what you did, and how you felt.',
   'storytelling',
   'A2',
   45,
   'past simple (regular and irregular verbs)',
   array['went', 'visited', 'stayed', 'had a good time', 'relaxed', 'tired', 'then']::text[],
   'Tell the events in order with ''first'', ''then'' and ''after that''.',
   'Practise past endings: visited (/ɪd/), played (/d/), walked (/t/).',
   '["where you went", "who you were with", "what you did", "how you felt"]'::jsonb,
   120,
   '{"task_type": "story", "model_opening": "My weekend was really nice, thanks.", "model_answer": "My weekend was really nice, thanks. On Saturday I visited my grandparents in their village with my parents. First we had lunch together, and then I helped my grandfather in the garden. In the evening we sat outside and talked for a long time. On Sunday I stayed at home and relaxed. I was a bit tired, but I felt very happy.", "cue_keywords": [["went", "go to", "visited", "stayed", "home", "house", "park", "village", "city", "centre", "market", "cinema", "mountains", "uncle", "aunt", "grandparents"], ["with", "family", "friend", "friends", "alone", "cousin", "parents", "brother", "sister", "grandparents"], ["played", "cooked", "watched", "walked", "ate", "bought", "cleaned", "read", "helped", "talked", "did"], ["felt", "happy", "tired", "great", "fun", "relaxed", "nice", "bored", "good time"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('describe-your-hometown',
   'Describe Your Hometown',
   'A visitor is coming to your town or city for the first time. Tell them where it is, what there is to see, what people do there, and one thing you like about it.',
   'guided_response',
   'A2',
   45,
   'there is / there are, and adjectives',
   array['there is', 'there are', 'famous for', 'busy', 'quiet', 'near', 'friendly']::text[],
   'Describe one place at a time and add an adjective to each one.',
   'Stress the important words, like the names of places.',
   '["where it is", "places to see", "what people do there", "what you like about it"]'::jsonb,
   130,
   '{"task_type": "describe", "model_opening": "I''m from Fergana, a green city in the east of Uzbekistan.", "model_answer": "I''m from Fergana, a green city in the east of Uzbekistan. There is a large park in the centre, and there are many small cafes. There is also a big bazaar where people sell fruit and silk. A lot of people work in shops or on farms near the city. I like it because the people are friendly and the streets are full of trees.", "cue_keywords": [["near", "north", "south", "east", "west", "valley", "mountains", "river", "kilometres", "capital", "region", "centre of"], ["there is", "there are", "park", "museum", "bazaar", "market", "square", "old town", "lake", "theatre", "cafe", "cafes"], ["work", "people", "farm", "farms", "factory", "shops", "students", "sell", "grow"], ["like", "love", "favourite", "best", "beautiful", "friendly", "quiet", "green"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('book-a-table-by-phone',
   'Book a Table by Phone',
   'You want to have dinner with friends at a restaurant on Friday. Call the restaurant. Say you want to book a table, give the day, time and number of people, ask one question, and give your name.',
   'roleplay',
   'A2',
   45,
   'polite requests: I''d like to …, Could we …?, Do you have …?',
   array['I''d like to book', 'a table for', 'at seven o''clock', 'Could we', 'Do you have', 'my name is']::text[],
   'Say each piece of information in a full, polite sentence.',
   'Say numbers and times slowly and clearly so the other person can write them down.',
   '["say you want to book a table", "day, time and number of people", "ask one question", "give your name"]'::jsonb,
   140,
   '{"task_type": "roleplay", "model_opening": "Hello, I''d like to book a table for Friday evening, please.", "model_answer": "Hello, I''d like to book a table for Friday evening, please. It''s for five people, at seven o''clock. Could we have a table near the window? Also, do you have any vegetarian dishes? One of my friends doesn''t eat meat. My name is Bekzod Karimov. Thank you very much. See you on Friday.", "cue_keywords": [["book", "table", "reservation", "reserve"], ["friday", "o''clock", "pm", "people", "evening", "for four", "for five", "for six", "for three"], ["do you", "could we", "can we", "can i", "is there", "have you", "menu", "parking", "vegetarian"], ["my name", "name is", "under the name", "it''s for"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('free-time-at-home-or-outside',
   'Free Time: At Home or Outside?',
   'Your teacher asks: ''Is it better to spend your free time at home or outside?'' Say your opinion, give two reasons, and give an example from your life.',
   'guided_response',
   'A2',
   45,
   'comparatives and because',
   array['I think', 'better than', 'because', 'healthier', 'relaxing', 'for example', 'also']::text[],
   'Start with your opinion, then give each reason in its own sentence.',
   'Stress the words that carry your opinion, like ''better'' and ''really''.',
   '["say your opinion", "give two reasons", "give an example from your life"]'::jsonb,
   150,
   '{"task_type": "opinion", "model_opening": "I think it''s better to spend free time outside.", "model_answer": "I think it''s better to spend free time outside. First, it''s healthier than sitting at home, because you move more and get fresh air. Also, you can meet friends and talk to new people. For example, every Sunday I play football in the park with my neighbours, and after that I feel much better. But when it''s very cold, I stay at home and read.", "cue_keywords": [["i think", "in my opinion", "i prefer", "better", "i believe"], ["because", "also", "first", "second", "another reason"], ["for example", "for instance", "every", "last", "when i", "usually", "yesterday"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('study-problem-and-solution',
   'Explain a Study Problem and Your Solution',
   'A younger student asks for your advice. Tell them about a problem you had with your studies, explain what caused it, say what you did to solve it, and say what you learned.',
   'guided_response',
   'B1',
   60,
   'past simple and past continuous; because and so',
   array['struggle with', 'fall behind', 'because of', 'decided to', 'a timetable', 'in the end', 'I realised']::text[],
   'Link your ideas with because, so, then and in the end.',
   'Pause briefly between the problem, the cause and the solution so each part is clear.',
   '["the problem", "what caused it", "what you did", "what you learned"]'::jsonb,
   210,
   '{"task_type": "explain", "model_opening": "Last year I really struggled with maths.", "model_answer": "Last year I really struggled with maths. My marks were getting worse every month, and I was falling behind the rest of the class. The main reason was my phone. While I was doing homework, I was checking messages all the time, so I couldn''t concentrate. In the end I decided to change my routine. I put my phone in another room and made a simple timetable: forty minutes of study, then a short break. I also asked a friend to explain the topics I didn''t understand. After two months my marks improved. I learned that small changes can make a big difference.", "cue_keywords": [["problem", "difficult", "hard", "struggled", "couldn''t", "failed", "bad mark", "low mark", "behind", "worse"], ["because", "caused", "reason", "since", "due to", "phone", "didn''t have time", "tired"], ["decided", "started", "tried", "made", "asked", "plan", "solved", "changed", "began", "timetable"], ["learned", "learnt", "realised", "realized", "now i", "lesson", "understand", "advice"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('complain-about-a-wrong-order',
   'Complain About a Wrong Online Order',
   'You ordered a pair of trainers online, but the shop sent the wrong size and the box was damaged. Call customer service. Explain what you ordered, describe the problem, say how you feel, and ask them to fix it.',
   'roleplay',
   'B1',
   60,
   'past simple; polite requests (Could you …? I''d like …)',
   array['I''m calling about', 'I ordered', 'the wrong size', 'damaged', 'disappointed', 'a refund', 'exchange', 'Could you']::text[],
   'Explain the problem in order: what happened, why it is a problem, and what you want.',
   'Keep your voice calm and polite, and stress the key facts like the size.',
   '["what you ordered", "what went wrong", "how you feel", "what you want them to do"]'::jsonb,
   220,
   '{"task_type": "roleplay", "model_opening": "Hello, I''m calling about an order I received yesterday.", "model_answer": "Hello, I''m calling about an order I received yesterday. Last week I ordered a pair of black trainers in size forty-two. Unfortunately, you sent me size thirty-nine, and they''re much too small. Also, the box was damaged when it arrived, so I''m worried the shoes aren''t new. To be honest, I''m quite disappointed, because I needed them for a trip this weekend. Could you send me the right size as soon as possible? If that isn''t possible, I''d like a full refund, please. Thank you for your help.", "cue_keywords": [["ordered", "bought", "order", "trainers", "shoes"], ["wrong", "damaged", "broken", "instead", "too small", "too big", "problem"], ["disappointed", "upset", "unhappy", "annoyed", "frustrated", "not happy", "angry"], ["refund", "exchange", "replace", "send me", "money back", "i''d like", "i would like", "could you", "can you"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('a-trip-you-remember',
   'A Trip You Remember',
   'Tell a friend about a trip or journey you remember well. Say where you went and who with, what happened, something that surprised you, and why you still remember it.',
   'storytelling',
   'B1',
   60,
   'past simple and past continuous (while we were …, suddenly …)',
   array['we set off', 'while we were', 'suddenly', 'it turned out', 'unforgettable', 'I''ll never forget', 'surprised']::text[],
   'Use time words like ''first'', ''while'', ''suddenly'' and ''in the end'' to tell the story in order.',
   'Slow down a little at the most exciting part of the story.',
   '["where you went and who with", "what happened", "something that surprised you", "why you remember it"]'::jsonb,
   230,
   '{"task_type": "story", "model_opening": "Two years ago I went on a trip to the mountains near Chimgan with my cousins.", "model_answer": "Two years ago I went on a trip to the mountains near Chimgan with my cousins. We set off very early in the morning and drove for about two hours. While we were walking up a hill, the weather suddenly changed. It started to rain heavily, and we got completely wet. We ran to a small house, and an old shepherd invited us in. He gave us hot tea and bread and told us stories about the mountains. That really surprised me, because he didn''t know us at all. I''ll never forget that trip, because it showed me how kind strangers can be.", "cue_keywords": [["went", "travelled", "traveled", "trip", "visited", "journey", "drove", "flew", "train"], ["happened", "first", "then", "after", "arrived", "while", "started"], ["surprised", "surprise", "suddenly", "didn''t expect", "unexpected", "amazing", "couldn''t believe", "turned out"], ["remember", "never forget", "still", "best", "special", "unforgettable"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('online-or-classroom-learning',
   'Online or Classroom Learning?',
   'In a class discussion, your teacher asks: ''Is it better to learn online or in a classroom?'' Give your opinion, explain one advantage and one disadvantage of online learning, and finish with a clear conclusion.',
   'guided_response',
   'B1',
   60,
   'giving opinions; comparatives; however and on the other hand',
   array['in my opinion', 'advantage', 'disadvantage', 'flexible', 'distracted', 'on the other hand', 'overall']::text[],
   'Use ''on the other hand'' and ''overall'' to move from one idea to the next.',
   'Put the stress on the right part of long words: ad-VAN-tage, dis-ad-VAN-tage.',
   '["your opinion", "an advantage of online learning", "a disadvantage of online learning", "a conclusion"]'::jsonb,
   240,
   '{"task_type": "opinion", "model_opening": "In my opinion, the best option is a mix of online and classroom learning.", "model_answer": "In my opinion, the best option is a mix of online and classroom learning, but if I have to choose, I prefer the classroom. Online learning has a big advantage: it''s very flexible. You can study at any time, and you can watch a lesson again if you didn''t understand it. On the other hand, it''s easy to get distracted at home, and you can feel lonely without classmates. Also, if your internet connection is bad, you miss things. In a classroom I can ask questions straight away and practise speaking with other people. Overall, I learn better face to face.", "cue_keywords": [["i think", "in my opinion", "i believe", "i prefer", "personally"], ["advantage", "flexible", "anywhere", "any time", "save time", "cheaper", "at home", "watch a lesson again", "again"], ["disadvantage", "distracted", "lonely", "internet", "connection", "hard to", "problem"], ["overall", "that''s why", "in the end", "to sum up", "so i", "in conclusion"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('explain-how-to-cook-a-dish',
   'Explain How to Cook a Dish From Your Region',
   'A friend from another country wants to cook a dish from your region. Say what the dish is, list the ingredients, explain the main steps, and give one tip to make it taste good.',
   'guided_response',
   'B1',
   60,
   'imperatives and sequencing words (first, then, after that)',
   array['ingredients', 'first', 'then', 'add', 'fry', 'cook for', 'make sure', 'finally']::text[],
   'Give each step in a short sentence that starts with a sequencing word.',
   'Say the ingredient words clearly, especially groups like ''carrots and onions''.',
   '["the dish", "the ingredients", "the main steps", "one useful tip"]'::jsonb,
   250,
   '{"task_type": "explain", "model_opening": "I''d like to explain how to cook plov, a very popular dish in Uzbekistan.", "model_answer": "I''d like to explain how to cook plov, a very popular dish in Uzbekistan. You need rice, meat, carrots, onions, oil, salt and cumin. First, heat the oil in a big, heavy pot and fry the meat until it''s brown. Then add the onions and the carrots, cut into long thin pieces, and cook them for about ten minutes. After that, add water and salt and let it cook slowly for half an hour. Next, wash the rice well and put it on top. Finally, cover the pot and cook it on low heat until the rice is soft. My tip: be patient, and never stir the rice.", "cue_keywords": [["dish", "called", "plov", "lagman", "shurpa", "manti", "soup", "samsa", "dumplings"], ["need", "ingredients", "rice", "meat", "carrots", "onions", "oil", "flour", "salt", "garlic"], ["first", "then", "next", "after that", "fry", "add", "cut", "boil", "finally"], ["tip", "make sure", "don''t", "never", "important", "secret", "remember", "patient"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('project-update-for-manager',
   'Give a Short Project Update',
   'Your manager asks for a quick spoken update on a project you are working on. Explain what has been finished, what is delayed and why, what you plan to do next, and what support you need.',
   'roleplay',
   'B2',
   90,
   'present perfect for results; going to and will for plans',
   array['we''ve completed', 'on schedule', 'behind schedule', 'the main issue', 'as a result', 'in the meantime', 'I''d appreciate', 'sign off on']::text[],
   'Organise the update into status, problem, next steps and request, with a clear phrase for each.',
   'Pause briefly before each new section so your manager can follow the structure.',
   '["what is finished", "what is delayed and why", "your next steps", "the support you need"]'::jsonb,
   310,
   '{"task_type": "roleplay", "model_opening": "Sure, here''s a quick update on the new website for the training centre.", "model_answer": "Sure, here''s a quick update on the new website for the training centre. So far, we''ve completed the design of the main pages, and the course catalogue is already working on the test site. However, the online payment page is behind schedule. The main issue is that we''re still waiting for the bank to send us the technical documents, so the developers can''t finish the connection. As a result, the launch will probably move to the middle of next month. In the meantime, we''re going to test everything else and fix the small bugs that users have reported. Next week I''m planning to run a short session with the support team so they''re ready for questions. To keep things moving, I''d appreciate it if you could contact the bank directly, as that might speed things up. I''d also need you to sign off on the new launch date by Friday.", "cue_keywords": [["finished", "completed", "done", "already", "ready", "we''ve"], ["delayed", "behind", "late", "waiting", "issue", "problem", "haven''t"], ["next", "plan", "going to", "will", "this week", "tomorrow", "next week"], ["need", "support", "help", "could you", "would you", "approve", "more time", "budget", "appreciate", "sign off"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('negotiate-a-deadline-extension',
   'Negotiate a Deadline Extension',
   'You need more time to finish an important report for your course or job. Speak to your tutor or manager. Explain the situation, ask for an extension, offer something in return, and suggest a new deadline you can both accept.',
   'roleplay',
   'B2',
   90,
   'polite requests and conditionals (Would it be possible …? If …, I could …)',
   array['would it be possible', 'an extension', 'I appreciate that', 'in return', 'a compromise', 'in the meantime', 'a first draft']::text[],
   'Move from problem to request to offer with clear linking phrases.',
   'Use a polite, rising tone for requests like ''Would it be possible …?''',
   '["explain the situation", "ask for more time", "offer something in return", "suggest a new deadline"]'::jsonb,
   320,
   '{"task_type": "roleplay", "model_opening": "Thank you for seeing me. I wanted to talk to you about the report that''s due this Friday.", "model_answer": "Thank you for seeing me. I wanted to talk to you about the report that''s due this Friday. Unfortunately, the survey data arrived a week later than we expected, so I''ve only been able to analyse about half of it. I''d rather hand in something complete and accurate than rush it. Would it be possible to have an extension until next Wednesday? I appreciate that this affects your schedule, so in return I could send you a first draft of the findings by Friday, as originally planned. That way you can check the direction and give me feedback early. In the meantime, I''ll keep you updated if anything else changes. If Wednesday is too late, I could manage Tuesday afternoon as a compromise. What do you think?", "cue_keywords": [["because", "unfortunately", "situation", "delayed", "took longer", "haven''t been able", "ill", "data", "only"], ["extension", "more time", "extra time", "extend", "would it be possible", "could i have"], ["in return", "i could", "i''ll", "i will", "send you", "draft", "update", "in the meantime"], ["deadline", "monday", "tuesday", "wednesday", "thursday", "friday", "next week", "days", "date"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('propose-a-transport-improvement',
   'Propose an Improvement to Local Transport',
   'You are giving a short presentation at a city youth forum. Propose one change that would improve public transport in your town or city. Describe the current problem, explain your idea, say who would benefit, and answer one possible objection.',
   'guided_response',
   'B2',
   90,
   'second conditional (If passengers could …, they would …)',
   array['at the moment', 'I''d like to propose', 'would benefit', 'in the long run', 'reduce traffic', 'some people might argue', 'however']::text[],
   'Signal each part of the talk: ''At the moment …'', ''My idea is …'', ''Some people might argue …''.',
   'Stress the key words of your proposal so the audience remembers them.',
   '["the current problem", "your idea", "who would benefit", "a possible objection"]'::jsonb,
   330,
   '{"task_type": "presentation", "model_opening": "Good afternoon, everyone. Today I''d like to propose a simple change to our buses.", "model_answer": "Good afternoon, everyone. Today I''d like to propose a simple change to our buses. At the moment, many buses in our city are crowded in the morning, and people often wait a long time without knowing when the next one will come. My idea is to introduce a live bus map in a free mobile app, and to add a few extra buses on the busiest routes between seven and nine in the morning. If passengers could see exactly where their bus is, they would plan their time better and feel less stressed. Students and workers would benefit most, but so would drivers, because fewer people would need to use their cars, which would help reduce traffic. Some people might argue that this is too expensive. However, GPS trackers are fairly cheap now, and in the long run a better service would bring more passengers and more income. Thank you for listening.", "cue_keywords": [["problem", "at the moment", "currently", "crowded", "traffic", "late", "wait", "not enough"], ["propose", "suggest", "idea", "introduce", "app", "lane", "extra buses", "more buses", "route"], ["benefit", "students", "workers", "older people", "passengers", "everyone", "drivers"], ["might argue", "might say", "objection", "expensive", "cost", "however", "although", "critics"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('working-from-home-your-view',
   'Working From Home: Your View',
   'A colleague says, ''Everyone should be allowed to work from home.'' Give your view. Discuss at least one benefit for workers and one risk for teams, and say under what conditions you would agree.',
   'guided_response',
   'B2',
   90,
   'linking words for contrast and condition (on the other hand, whereas, as long as)',
   array['in my view', 'commute', 'productive', 'isolated', 'as long as', 'on the other hand', 'a balance', 'face-to-face']::text[],
   'Present both sides, then give a clear conclusion.',
   'Use stress to show contrast: ''It SAVES time, but it can HURT teamwork.''',
   '["your view", "a benefit for workers", "a risk for teams", "conditions you would accept"]'::jsonb,
   340,
   '{"task_type": "opinion", "model_opening": "In my view, working from home should be an option, but not for everyone all the time.", "model_answer": "In my view, working from home should be an option, but not for everyone all the time. For workers, the biggest benefit is time. You don''t have to commute, so you have more energy for work and for your family. Many people also find they''re more productive at home, because it''s quieter than an open office. On the other hand, there are real risks for teams. When people never meet, communication becomes slower, and new staff can feel isolated, because they can''t just turn to a colleague and ask a quick question. So I''d agree with the idea as long as there''s a balance: for example, two or three days at home and the rest in the office, with regular face-to-face meetings. That way, people keep the flexibility, and the team still feels like a team.", "cue_keywords": [["i think", "in my view", "in my opinion", "i believe", "i partly agree", "i agree", "i disagree", "personally"], ["benefit", "advantage", "save time", "commute", "flexible", "family", "quiet", "productive"], ["risk", "disadvantage", "isolated", "lonely", "communication", "teamwork", "new staff", "trust"], ["as long as", "provided", "only if", "condition", "days", "depends", "balance"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('a-difficult-decision',
   'A Difficult Decision You Made',
   'Tell someone about a difficult decision you had to make, for example about your studies, work or where to live. Explain the options you had, what you considered, what you decided, and whether you would make the same choice again.',
   'storytelling',
   'B2',
   90,
   'past perfect and the third conditional (If I had …, I wouldn''t have …)',
   array['I had to choose between', 'on the one hand', 'on the other hand', 'in the end', 'looking back', 'I''m glad', 'regret']::text[],
   'Tell the story in order, then step back and reflect on it.',
   'Say contractions naturally in conditionals: ''If I''d stayed'', ''I wouldn''t have''.',
   '["the options you had", "what you considered", "what you decided", "would you do it again"]'::jsonb,
   350,
   '{"task_type": "story", "model_opening": "A few years ago I had to choose between two universities.", "model_answer": "A few years ago I had to choose between two universities. One was in my home town, so I could live with my family and save money. The other was in the capital and had a much better programme in computer science, but I''d have to rent a room and find a part-time job. On the one hand, I was worried about the cost and about being alone. On the other hand, I knew the programme in the capital would give me more opportunities. I talked to my parents and to a teacher I trusted, and in the end I chose the capital. The first year was hard, and I often felt homesick. But looking back, I''m glad I went. If I had stayed at home, I wouldn''t have met the people who later helped me find my first job. So yes, I''d make the same choice again, and I don''t regret it.", "cue_keywords": [["option", "choice", "choose", "either", "offer", "stay", "leave"], ["considered", "thought about", "worried", "on the one hand", "on the other hand", "pros", "cons", "money", "family", "future"], ["decided", "chose", "in the end", "finally", "accepted", "turned down"], ["again", "regret", "same choice", "if i had", "if i''d", "would have", "wouldn''t have", "glad", "looking back"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('smartphones-and-concentration',
   'Are Smartphones Harming Concentration?',
   'In a panel discussion you are asked: ''Are smartphones damaging young people''s ability to concentrate?'' Give a balanced answer. Acknowledge the concerns, present a counter-argument, give an example from your own experience, and reach a clear conclusion.',
   'guided_response',
   'C1',
   120,
   'hedging and concession (admittedly, it could be argued that, while it''s true that …)',
   array['admittedly', 'it could be argued', 'constant notifications', 'attention span', 'on balance', 'self-discipline', 'ultimately']::text[],
   'Structure a two-minute answer: position, concession, counter-argument, example, conclusion.',
   'Vary your intonation to show contrast and emphasis, especially around ''admittedly'' and ''that said''.',
   '["acknowledge the concerns", "a counter-argument", "a personal example", "a clear conclusion"]'::jsonb,
   410,
   '{"task_type": "opinion", "model_opening": "It''s a fair question, and I think the honest answer is: partly, but not in the way people often suggest.", "model_answer": "It''s a fair question, and I think the honest answer is: partly, but not in the way people often suggest. Admittedly, the concerns are real. Phones are designed to keep us looking at them, and constant notifications make it very hard to stay with one task for long. Many teachers say that students find long texts harder to read than they used to. That said, it could be argued that the problem isn''t so much the device as the habits we build around it. The same phone that distracts you can also hold a dictionary, a timer and an entire library. In my case, I used to check my messages every few minutes while I was studying, and I genuinely couldn''t get through a chapter. What changed things wasn''t giving the phone up, but turning off almost all notifications and leaving it in another room for an hour at a time. Within a few weeks, I could focus for much longer. So, on balance, I''d say smartphones can weaken concentration, but mainly when nobody teaches young people how to manage them. Ultimately, rather than banning phones, schools and families should treat self-discipline with technology as a skill, and teach it explicitly.", "cue_keywords": [["concern", "worry", "worried", "notifications", "distract", "attention", "harm", "damage", "addictive", "admittedly"], ["however", "on the other hand", "that said", "then again", "depends", "how we use", "habits", "tool", "counter"], ["for example", "in my case", "personally", "i''ve noticed", "i used to", "myself"], ["overall", "on balance", "in conclusion", "to sum up", "ultimately", "so i''d say", "the real issue"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('mediate-a-team-disagreement',
   'Mediate a Team Disagreement',
   'You lead a small project team. Two members disagree: one wants to launch the product next month as planned, the other wants to delay it to fix quality problems. Speak to both of them. Summarise each position fairly, identify what they agree on, propose a compromise, and agree on next steps.',
   'roleplay',
   'C1',
   120,
   'paraphrasing and suggesting (What I''m hearing is …, What if we …?, I''d suggest …)',
   array['if I''ve understood correctly', 'common ground', 'a phased launch', 'the trade-off', 'I''d suggest', 'meet halfway', 'going forward', 'take ownership of']::text[],
   'Keep a calm, even pace and signal each step: summary, common ground, proposal, actions.',
   'Use a falling tone to sound confident when you propose the solution.',
   '["summarise both positions", "find common ground", "propose a compromise", "agree on next steps"]'::jsonb,
   420,
   '{"task_type": "roleplay", "model_opening": "Thanks, both of you, for being so open about this.", "model_answer": "Thanks, both of you, for being so open about this. Let me check I''ve understood correctly. Aziz, your main concern is the date: we promised the client a launch next month, and if we delay, we risk losing their trust. Malika, you''re worried that if we launch with the current bugs, users will have a bad first experience, and that would damage trust even more. So, actually, you''re both trying to protect the same thing: our relationship with the client. That''s our common ground. What I''d suggest is a phased launch. We go live next month as planned, but only with the core features that have passed testing. The two features with known problems stay switched off until they''re fixed, ideally within three weeks. That way we keep our promise, and we don''t show users something that isn''t ready. The trade-off is that the first version will be smaller, so we''ll need to explain that clearly to the client. Going forward, Malika, could you take ownership of a list of what''s ready by Thursday? Aziz, could you talk to the client about the phased plan? Let''s meet again on Friday to confirm. Does that sound fair to both of you?", "cue_keywords": [["understood", "you feel", "your point", "you''re saying", "your main concern", "worried", "concern", "position"], ["both", "common ground", "agree", "same thing", "same goal", "we all"], ["compromise", "what if", "how about", "suggest", "propose", "phased", "halfway", "middle"], ["next steps", "by thursday", "by friday", "let''s", "meet again", "could you", "going forward", "follow up", "deadline"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('the-role-of-the-local-bazaar',
   'Present the Role of the Local Bazaar',
   'You are giving a short talk to international students who have just arrived in your city. Explain the role the traditional bazaar plays in local life: what happens there, why it matters beyond shopping, how it is changing, and what visitors should know.',
   'guided_response',
   'C1',
   120,
   'relative clauses and the present continuous for change (… is becoming, increasingly …)',
   array['at the heart of', 'a meeting place', 'haggling', 'regular customers', 'word of mouth', 'increasingly', 'whereas', 'it''s worth']::text[],
   'Use signposting so listeners can follow: ''On the surface …'', ''What''s interesting is …'', ''So, a few tips …''.',
   'Group words into meaningful chunks and pause between them, rather than speaking word by word.',
   '["what happens there", "why it matters beyond shopping", "how it is changing", "advice for visitors"]'::jsonb,
   430,
   '{"task_type": "presentation", "model_opening": "If you want to understand this city, the best place to start is the bazaar.", "model_answer": "Welcome, everyone. If you want to understand this city, the best place to start is the bazaar. On the surface, it''s simply a market. You''ll find rows of stalls selling fresh bread, dried fruit, spices and vegetables that arrived from nearby villages that morning. But for many people, the bazaar is at the heart of community life. It''s a meeting place where neighbours catch up, where news travels by word of mouth, and where long relationships are built. Many families have bought from the same traders for years, and those regular customers often get the best produce or a small discount, simply because of trust. What''s interesting is how the bazaar is changing. Younger people increasingly shop in supermarkets or order online, and some markets have been renovated with covered halls and card payments. Whereas some people miss the old atmosphere, others welcome the cleaner, more organised spaces. So, a few tips for visitors. Go in the morning, when everything is freshest. Bring some cash, although card payments are becoming more common. And don''t be afraid of haggling: it''s expected, and it''s usually friendly. Above all, take your time and talk to people. It''s worth it.", "cue_keywords": [["sell", "buy", "stalls", "traders", "fruit", "spices", "bread", "vegetables", "market"], ["meeting place", "community", "social", "relationships", "news", "tradition", "trust", "neighbours", "heart of"], ["changing", "change", "supermarkets", "online", "renovated", "younger", "increasingly", "nowadays", "card"], ["visitors", "tip", "tips", "advice", "go in the morning", "cash", "haggling", "bargain", "don''t be afraid", "take your time"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('why-freelancing-is-growing',
   'Explain Why Freelancing Is Growing',
   'A relative who has always had a traditional office job asks you why so many young people now work as freelancers online. Explain the main reasons, the benefits and the risks, and say what advice you would give someone who wants to start.',
   'guided_response',
   'C1',
   120,
   'cause and effect (this has led to, as a result of, which means that)',
   array['this has led to', 'a steady income', 'clients abroad', 'a portfolio', 'on the downside', 'a safety net', 'burnout', 'it pays to']::text[],
   'Explain one cause at a time and link each cause clearly to its effect.',
   'Stress the key contrast words when you compare office work and freelancing.',
   '["the main reasons", "the benefits", "the risks", "your advice"]'::jsonb,
   440,
   '{"task_type": "explain", "model_opening": "I think there are a few reasons, and most of them come down to the internet.", "model_answer": "I think there are a few reasons, and most of them come down to the internet. Today, a designer, translator or programmer in Tashkent can work for clients abroad without leaving home. Online platforms connect people with work, and payments that used to be complicated are now much easier. This has led to a whole generation seeing their skills, rather than their employer, as their main security. The benefits are obvious. Freelancers choose their projects and their hours, and if they''re good, they can sometimes earn more than in a local office job. They also build international experience, which looks great on a CV. On the downside, though, the income isn''t steady. One month can be busy and the next almost empty. There''s usually no paid holiday or sick leave, and many freelancers end up working late into the night, which can lead to burnout. Competition is also fierce, because you''re competing with people all over the world. So my advice would be: don''t quit a stable job overnight. Start with small projects in your free time, build a portfolio, and save enough money to cover a few months of expenses as a safety net. It pays to be patient.", "cue_keywords": [["because", "reason", "internet", "platforms", "online", "technology", "remote", "abroad", "has led to"], ["benefit", "advantage", "freedom", "flexible", "choose", "earn", "international", "independent"], ["risk", "downside", "steady", "irregular", "sick leave", "holiday", "competition", "burnout", "uncertain"], ["advice", "recommend", "should", "start with", "portfolio", "save", "safety net", "don''t quit"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('cities-for-people-or-cars',
   'Should Cities Put Pedestrians Before Cars?',
   'At a public debate on the future of your city, you are asked whether city centres should be redesigned to put pedestrians and public transport before private cars. Present a nuanced argument: weigh the competing interests, address the strongest objection, propose how such a change could be introduced fairly, and conclude persuasively.',
   'guided_response',
   'C2',
   150,
   'advanced concession and emphasis (It would be naive to …, Not only … but …, What is at stake is …)',
   array['competing interests', 'it would be naive to', 'the strongest objection', 'a pilot scheme', 'disproportionately', 'by the same token', 'what is at stake']::text[],
   'Sustain a long turn with clear signposting, and vary sentence length for effect.',
   'Use pausing and emphasis to make your key points stand out, especially in the conclusion.',
   '["weigh the competing interests", "address the strongest objection", "a fair way to introduce change", "a persuasive conclusion"]'::jsonb,
   510,
   '{"task_type": "opinion", "model_opening": "Let me start by saying that this isn''t a simple choice between people and cars.", "model_answer": "Let me start by saying that this isn''t a simple choice between people and cars. It''s a question of whose needs a city centre should serve first, and the interests involved genuinely compete. Residents want cleaner air and safer streets; commuters who drive want to reach work on time; and shopkeepers want customers to be able to reach them. It would be naive to pretend that any redesign could please everyone equally. The strongest objection, in my view, is that restricting cars could hit certain groups disproportionately: older people, people with disabilities, and tradespeople who carry heavy tools. That concern deserves to be taken seriously rather than dismissed. But it''s an argument for designing the change carefully, not for avoiding it. So how might it be done fairly? Not by closing the centre overnight, but by starting with a pilot scheme on one or two streets, perhaps at weekends, and measuring what actually happens to footfall and journey times. Public transport would have to improve before any restrictions were extended, and there would need to be exemptions for deliveries, taxis and people with limited mobility. Crucially, residents and businesses should be consulted at every stage. By the same token, we should be honest about what is at stake if we do nothing: more congestion, more noise, and streets designed for parking rather than for living. Ultimately, a city centre is a shared space. If we can make it work better for the many without abandoning the few, I''d argue that change is not only possible, but overdue.", "cue_keywords": [["interests", "residents", "drivers", "commuters", "businesses", "shopkeepers", "pedestrians", "whereas", "balance"], ["objection", "critics", "argue", "concern", "disproportionately", "admittedly", "older people", "disabilities"], ["gradually", "pilot", "trial", "consult", "step by step", "exemptions", "fairly", "phase"], ["ultimately", "to conclude", "in short", "what is at stake", "overdue", "shared space", "therefore"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb),
  ('what-failure-teaches-us',
   'What Failure Teaches Us',
   'You have been invited to give a short, reflective talk to final-year students on the theme ''What failure teaches us''. Tell the story of a setback you experienced, analyse why it happened, reflect on what it changed in you, and draw a wider lesson without sounding clichéd.',
   'storytelling',
   'C2',
   150,
   'narrative tenses with reflective structures (What I hadn''t realised was …, It was only later that …)',
   array['a setback', 'in hindsight', 'overconfident', 'it was only later that', 'resilience', 'take it personally', 'a turning point', 'for what it''s worth']::text[],
   'Move smoothly between telling the story and reflecting on it, using pauses to let key moments land.',
   'Slow down slightly for the reflective parts and let the key sentence of each section stand out.',
   '["the story of a setback", "why it happened", "what it changed in you", "a wider lesson"]'::jsonb,
   520,
   '{"task_type": "story", "model_opening": "When I was nineteen, I failed an exam that I had been completely sure I would pass.", "model_answer": "When I was nineteen, I failed an exam that I had been completely sure I would pass. It was the entrance exam for a programme I had dreamed about for years, and I remember reading the results list three times, convinced there had been a mistake. There hadn''t. In hindsight, the reasons were fairly clear. I had been the best student in my class at school, and I was overconfident. I had studied what I enjoyed and quietly skipped what I found difficult, assuming my talent would cover the gaps. What I hadn''t realised was that the exam was designed precisely to find those gaps. For a few weeks, I took it very personally. I felt that the result said something about who I was, not just about how I had prepared. It was only later that I started to see it differently. When I prepared again the following year, I began with my weakest topics, asked for feedback I didn''t want to hear, and kept a record of every mistake I made. I passed, but more importantly, I had changed how I learn. So, for what it''s worth, here''s the lesson I''d offer. Failure isn''t valuable in itself; plenty of people fail and learn nothing. What makes it useful is the honesty with which you examine it. If you can look at a setback and ask, calmly, ''What exactly did this reveal?'', it can become a turning point rather than a verdict.", "cue_keywords": [["failed", "failure", "setback", "rejected", "didn''t get", "lost", "went wrong"], ["in hindsight", "looking back", "reason", "because", "overconfident", "underestimated", "hadn''t realised", "hadn''t realized", "assumed"], ["changed", "taught me", "learned", "learnt", "since then", "began", "realised", "realized", "how i learn"], ["lesson", "what makes", "the point", "what matters", "ultimately", "turning point", "for what it''s worth"]], "seeded_by": "20261022151000_english_speaking_prompts"}'::jsonb)
) as v(slug, title, prompt_text, prompt_type, level, target_duration_seconds, target_grammar,
       target_vocabulary, fluency_objective, pronunciation_objective, cue_points, sort_order, metadata)
cross join lateral (
  select pr.id from public.products pr
  where lower(coalesce(pr.metadata->>'slug', '')) = 'english-speaking'
  order by pr.created_at asc
  limit 1
) p
cross join lateral (
  select la.id from public.languages la where la.code = 'en' limit 1
) l
on conflict (product_id, language_id, slug) do update
set
  title = excluded.title,
  prompt_text = excluded.prompt_text,
  prompt_type = excluded.prompt_type,
  level = excluded.level,
  target_duration_seconds = excluded.target_duration_seconds,
  target_grammar = excluded.target_grammar,
  target_vocabulary = excluded.target_vocabulary,
  fluency_objective = excluded.fluency_objective,
  pronunciation_objective = excluded.pronunciation_objective,
  cue_points = excluded.cue_points,
  status = excluded.status,
  sort_order = excluded.sort_order,
  metadata = coalesce(public.speaking_prompts.metadata, '{}'::jsonb) || excluded.metadata,
  updated_at = now();

insert into public.learning_content_registry_items (
  product_id, language_id, service_key, content_type, source_table, source_record_id, source_ref,
  title, description, skill_key, subskill_keys, cefr_level, difficulty, estimated_minutes,
  learning_objective, tags, status, payload_json, metadata
)
select
  sp.product_id,
  sp.language_id,
  'speaking',
  'speaking.prompt',
  'speaking_prompts',
  sp.id,
  sp.slug,
  sp.title,
  left(sp.prompt_text, 900),
  'speaking',
  array['speaking.fluency', 'speaking.grammar', 'speaking.task_completion', 'vocabulary.usage']::text[],
  sp.level,
  case sp.level
    when 'A1' then 0.20
    when 'A2' then 0.30
    when 'B1' then 0.45
    when 'B2' then 0.60
    when 'C1' then 0.75
    when 'C2' then 0.90
    else 0.50
  end,
  ceil(sp.target_duration_seconds / 60.0)::int + 4,
  coalesce(sp.fluency_objective, sp.prompt_text),
  array_remove(array[sp.metadata->>'task_type', sp.target_grammar], null),
  'published',
  jsonb_build_object(
    'task_type', sp.metadata->>'task_type',
    'prompt_type', sp.prompt_type,
    'target_duration_seconds', sp.target_duration_seconds,
    'target_grammar', sp.target_grammar,
    'target_vocabulary', sp.target_vocabulary,
    'cue_points', sp.cue_points
  ),
  jsonb_build_object('seeded_by', '20261022151000_english_speaking_prompts')
from public.speaking_prompts sp
where sp.metadata->>'seeded_by' = '20261022151000_english_speaking_prompts'
  and sp.status = 'published'
on conflict (language_id, service_key, content_type, source_ref) do update
set
  source_record_id = excluded.source_record_id,
  title = excluded.title,
  description = excluded.description,
  skill_key = excluded.skill_key,
  subskill_keys = excluded.subskill_keys,
  cefr_level = excluded.cefr_level,
  difficulty = excluded.difficulty,
  estimated_minutes = excluded.estimated_minutes,
  learning_objective = excluded.learning_objective,
  tags = excluded.tags,
  status = excluded.status,
  payload_json = excluded.payload_json,
  metadata = coalesce(public.learning_content_registry_items.metadata, '{}'::jsonb) || excluded.metadata,
  updated_at = now();
